function initSearchOverlay() {
  var overlay = document.querySelector(".searchform-wrap");
  if (!overlay) return;
  var input = overlay.querySelector("input[name='q']");
  function openOverlay() {
    overlay.style.opacity = "0";
    overlay.style.display = "block";
    requestAnimationFrame(function () { overlay.style.opacity = "1"; });
    if (input) input.focus();
  }
  function closeOverlay() {
    overlay.style.opacity = "0";
    setTimeout(function () { overlay.style.display = "none"; }, 150);
  }
  document.querySelectorAll(".mino-serch").forEach(function (btn) {
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      openOverlay();
    });
  });
  var closeBtn = overlay.querySelector(".btn-mini-close");
  if (closeBtn) closeBtn.addEventListener("click", closeOverlay);
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && overlay.style.display === "block") closeOverlay();
  });
}
initSearchOverlay();
