//main
// ---- Shared helpers ----
function minoFetchFeed(path, onSuccess, onError) {
  fetch(path).then(function (response) {
    if (!response.ok) throw new Error("HTTP " + response.status);
    return response.json();
  }).then(onSuccess).catch(onError || function () {});
}

function minoEntryUrl(entry) {
  for (var k = 0; k < entry.link.length; k++) {
    if (entry.link[k].rel === "alternate") return entry.link[k].href;
  }
  return "#";
}

function minoAttr(value) {
  return String(value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

// Swap the size segment of a Blogger image URL (s72-c, s1600, w400-h300-...)
// for the requested one; YouTube thumbs get the medium-quality variant
function minoResizeImage(url, size) {
  if (!url) return url;
  if (url.indexOf("img.youtube.com") > -1) {
    return url.replace("/hqdefault.jpg", "/mqdefault.jpg").replace("/default.jpg", "/mqdefault.jpg");
  }
  return url.replace(/\/(s|w)\d+[^\/]*\//, "/" + size + "/");
}

function minoEntryImage(entry, size) {
  var content = entry.content ? entry.content.$t : (entry.summary ? entry.summary.$t : "");
  var img = "";
  if (content.indexOf("//www.youtube.com/embed/") > -1 && entry.media$thumbnail) {
    img = entry.media$thumbnail.url;
  } else if (content.indexOf("<img") > -1) {
    // DOMParser documents are inert, so this never downloads the post's images
    var doc = new DOMParser().parseFromString(content, "text/html");
    var first = doc.querySelector("img");
    if (first) img = first.getAttribute("src") || "";
  }
  if (!img && entry.media$thumbnail) img = entry.media$thumbnail.url;
  if (!img) return no_image;
  return minoResizeImage(img, size);
}

function minoFormatShortDate(published) {
  return month_format[parseInt(published.substring(5, 7), 10)] + " " + published.substring(8, 10) + ", " + published.substring(0, 4);
}

var MINO_NO_THUMB = "https://4.bp.blogspot.com/-wPwjv7-YYGY/Wc98wlDT8qI/AAAAAAAAAEE/mH8YkPl8qJAH9FMuFKcShQvXXYMmVyrIgCLcBGAs/s1600/notfound.png";

// ---- Main navigation: rebuild the flat LinkList into a nested menu ----
// Nesting depth is encoded with leading underscores in the link names
function initMainMenu() {
  var menu = document.getElementById("mino-menu");
  if (!menu) return;
  var linkList = menu.querySelector(".LinkList");
  if (!linkList) return;
  var html = "";
  var level = -1;
  linkList.querySelectorAll("ul li").forEach(function (li) {
    var link = li.querySelector("a");
    if (!link) return;
    var text = li.textContent;
    var depth = (text.match(/_/g) || []).length;
    if (depth > level) html += "<ul>";
    if (depth < level) {
      for (var k = 0; k < level - depth; k++) html += "</ul></li>";
    }
    html += "<li><a href='" + link.getAttribute("href") + "'>" + text.replace(/_/g, "") + "</a>";
    level = depth;
  });
  for (var k = 0; k <= level; k++) {
    html += "</ul>";
    if (k !== 0) html += "</li>";
  }
  linkList.innerHTML = html;
  var topMenu = linkList.querySelector("ul");
  if (topMenu) topMenu.id = "mino_menu";
  document.querySelectorAll("#mino_menu a").forEach(function (a) {
    var href = (a.getAttribute("href") || "").toLowerCase();
    if (href.indexOf("[mega menu]") !== -1) {
      a.classList.add("mega-link");
      a.setAttribute("href", "/search/label/" + a.textContent + "?&max-results=" + perPage);
    }
  });
  selectnav("mino_menu");
  menu.querySelectorAll("ul > li > ul").forEach(function (sub) {
    sub.parentElement.classList.add("hasSubmenu");
  });
  menu.querySelectorAll(".widget").forEach(function (w) { w.setAttribute("style", "display:block!important;"); });
}

// ---- Mega menus: [mega menu] links get a paged grid of label posts ----
function minoMegaItemHtml(entry) {
  var thumb = entry.media$thumbnail ? minoResizeImage(entry.media$thumbnail.url, "s400") : MINO_NO_THUMB;
  var url = minoEntryUrl(entry);
  return '<div class="mino-mega-item col-sm-3"><div class="mino-m-thumb" style="background:url(\'' + thumb + '\')"><a aria-label="' + minoAttr(entry.title.$t) + '" class="linkcover" href="' + url + '"></a></div><div class="mino-text"><a href="' + url + '">' + entry.title.$t + "</a></div></div>";
}

function minoMegaImageUrls(entries) {
  return entries.map(function (entry) {
    return entry.media$thumbnail ? minoResizeImage(entry.media$thumbnail.url, "s400") : MINO_NO_THUMB;
  });
}

// Resolves once every image is cached (capped at 2.5s) so page flips swap in one paint
function minoPreloadImages(urls) {
  return new Promise(function (resolve) {
    var pending = urls.length;
    if (!pending) return resolve();
    var done = false;
    function finish() { if (!done) { done = true; resolve(); } }
    setTimeout(finish, 2500);
    urls.forEach(function (u) {
      var img = new Image();
      img.onload = img.onerror = function () { pending--; if (pending <= 0) finish(); };
      img.src = u;
    });
  });
}

function initMegaMenus() {
  document.querySelectorAll("#mino_menu a.mega-link").forEach(function (link) {
    var label = link.textContent;
    function feedPath(startIndex, count) {
      return "/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&start-index=" + startIndex + "&max-results=" + count;
    }
    minoFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&max-results=4", function (data) {
      var item = link.closest("li");
      if (item) {
        item.classList.add("isMega");
        item.classList.add("hasSubmenu");
      }
      (data.feed.link || []).forEach(function (l) {
        if (l.rel === "alternate" && l.type === "text/html") link.setAttribute("href", l.href + "?&max-results=" + perPage);
      });
      if (!data.feed.entry) return;
      var total = parseInt(data.feed.openSearch$totalResults.$t, 10);
      var perStage = parseInt(data.feed.openSearch$itemsPerPage.$t, 10);
      var stageCount = Math.ceil(total / perStage);
      var stageCache = { 1: data.feed.entry };
      var currentStage = 1;
      var busy = false;
      link.insertAdjacentHTML("afterend", '<ul>' +
        '<div class="mega-nav"><a aria-label="Previous posts" class="mega-prev disable" href="javascript:;" role="button"><i aria-hidden="true" class="fa-solid fa-arrow-left"></i></a><a aria-label="Next posts" class="mega-next' + (stageCount > 1 ? '' : ' disable') + '" href="javascript:;" role="button"><i aria-hidden="true" class="fa-solid fa-arrow-right"></i></a></div>' +
        '<div class="mega-spinner" style="display:none"></div>' +
        '<div class="mega-inner row">' + data.feed.entry.map(minoMegaItemHtml).join("") + "</div></ul>");
      var mega = link.nextElementSibling;
      var inner = mega.querySelector(".mega-inner");
      var prevBtn = mega.querySelector(".mega-prev");
      var nextBtn = mega.querySelector(".mega-next");
      var spinner = mega.querySelector(".mega-spinner");
      function setBusy(on) {
        busy = on;
        inner.classList.toggle("mega-busy", on);
        spinner.style.display = on ? "block" : "none";
      }
      // Quietly fetch a neighboring page and warm its images so the flip is instant
      function prefetchStage(stage) {
        if (stage < 1 || stage > stageCount || stageCache[stage]) return;
        minoFetchFeed(feedPath((stage - 1) * perStage + 1, perStage), function (page) {
          stageCache[stage] = page.feed.entry || [];
          minoMegaImageUrls(stageCache[stage]).forEach(function (u) {
            var img = new Image();
            img.src = u;
          });
        });
      }
      function showStage(stage) {
        var entries = stageCache[stage];
        minoPreloadImages(minoMegaImageUrls(entries)).then(function () {
          inner.innerHTML = entries.map(minoMegaItemHtml).join("");
          currentStage = stage;
          prevBtn.classList.toggle("disable", stage <= 1);
          nextBtn.classList.toggle("disable", stage >= stageCount);
          setBusy(false);
          prefetchStage(stage + 1);
          prefetchStage(stage - 1);
        });
      }
      function loadStage(forward) {
        if (busy) return;
        var target = forward ? currentStage + 1 : currentStage - 1;
        if (target < 1 || target > stageCount) return;
        setBusy(true);
        if (stageCache[target]) return showStage(target);
        minoFetchFeed(feedPath((target - 1) * perStage + 1, perStage), function (page) {
          stageCache[target] = page.feed.entry || [];
          showStage(target);
        }, function () { setBusy(false); });
      }
      prevBtn.addEventListener("click", function () { loadStage(false); });
      nextBtn.addEventListener("click", function () { loadStage(true); });
      prefetchStage(2);
    });
  });
}

// ---- FeaturedPost widget: use the post image as the card background ----
function initFeaturedPostWidget() {
  document.querySelectorAll(".FeaturedPost .post-summary").forEach(function (card) {
    var image = card.querySelector(".image");
    if (image && image.getAttribute("src")) {
      card.setAttribute("style", "background-image:url(" + minoResizeImage(image.getAttribute("src"), "s800") + ");");
    }
    card.insertAdjacentHTML("beforeend", "<div class='overlay'></div>");
  });
}

// ---- Index thumbnails: swap Blogger's tiny 72px thumbs for sized versions ----
function minoUpgradeThumb(value, size) {
  if (value.indexOf("hqdefault.jpg") > -1) return value.replace("/hqdefault.jpg", "/mqdefault.jpg");
  if (value.indexOf("default.jpg") > -1) return value.replace("/default.jpg", "/mqdefault.jpg");
  if (value.indexOf("/s72-c") > -1) return value.replace("/s72-c", "/" + size);
  if (value.indexOf("/w72-h72-p-nu") > -1) return value.replace("/w72-h72-p-nu", "/" + size);
  return value;
}

function initPostThumbnails() {
  // Server-rendered post cards carry full-size firstImageUrl originals;
  // swap them for right-sized variants before the browser fetches them
  document.querySelectorAll("img.mino-featured-wid").forEach(function (img) {
    var src = img.getAttribute("src");
    if (src) img.setAttribute("src", minoResizeImage(src, "s800"));
  });
  document.querySelectorAll("div.mino-featured-wid").forEach(function (div) {
    var style = div.getAttribute("style");
    if (style) div.setAttribute("style", minoResizeImage(style, "s800"));
  });
  document.querySelectorAll(".post-home-image .post-thumb a").forEach(function (a) {
    var style = a.getAttribute("style");
    if (style) a.setAttribute("style", minoUpgradeThumb(style, "s800"));
  });
  document.querySelectorAll(".PopularPosts ul li img").forEach(function (img) {
    var src = img.getAttribute("src");
    if (src) img.setAttribute("src", minoUpgradeThumb(src, "s400"));
  });
}

// ---- Move author bio, author social links and post ads into the article ----
function minoMoveWidgetContent(targetSelector, sourceSelector) {
  var target = document.querySelector(targetSelector);
  var source = document.querySelector(sourceSelector);
  if (!target || !source) return;
  target.insertAdjacentHTML("beforebegin", source.innerHTML);
  source.innerHTML = "";
}

function initPostInjections() {
  minoMoveWidgetContent('span[name="author-social"]', ".post-author-social .widget-content");
  minoMoveWidgetContent('span[name="author-post"]', ".post-author-widget .widget-content");
  minoMoveWidgetContent('a[name="ad-post-top"]', "#mino-advert-2 .widget-content");
  minoMoveWidgetContent('a[name="ad-post-bottom"]', "#mino-advert-3 .widget-content");
}

// ---- Featured grid (homepage hero + two secondary posts) ----
function initFeaturedGrid() {
  document.querySelectorAll(".mino_featured_widget .HTML .widget-content").forEach(function (content) {
    var span = content.querySelector("span");
    if (!span || (span.getAttribute("data-type") || "").indexOf("minofeatured") === -1) return;
    // The wrapper is display:none outside the homepage - skip the feed request there
    var wrapper = content.closest(".feturepostwidgetmino");
    if (wrapper && getComputedStyle(wrapper).display === "none") return;
    var label = span.getAttribute("data-label");
    minoFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&max-results=3", function (data) {
      var html = '<div class="mino-featured">';
      if (data.feed.entry) {
        data.feed.entry.forEach(function (entry, index) {
          var url = minoEntryUrl(entry);
          var title = entry.title.$t;
          var category = entry.category && entry.category[0] ? entry.category[0].term : "";
          var author = entry.author[0].name.$t;
          var date = minoFormatShortDate(entry.published.$t);
          var image = minoEntryImage(entry, index === 0 ? "s1200" : "s600");
          var labelHtml = '<div class="mino-label"><a class="icon ' + category + '" href="/search/label/' + category + '">' + category + "</a></div>";
          var metaHtml = '<h3 class="minofeatured-title"><a href="' + url + '">' + title + '</a></h3><span class="mino-author">' + author + '</span><span class="mino-time">' + date + "</span>";
          if (index === 0) {
            // The hero is the homepage LCP element - start fetching it right away
            var hero = new Image();
            hero.fetchPriority = "high";
            hero.src = image;
            html += '<div class="mino-hero"><div class="mino-featured-image"><div class="minofeatured-thumb"><a aria-label="' + minoAttr(title) + '" class="blsm-img" href="' + url + '" style="background:url(' + image + ') no-repeat center center;background-size: cover"><span class="mino-trap"></span></a></div><div class="mino-hero-content">' + labelHtml + metaHtml + "</div></div></div>";
          } else {
            html += '<div class="mino-secondary"><div class="minofeatured-thumb"><a aria-label="' + minoAttr(title) + '" class="mino-thumb" href="' + url + '" style="background:url(' + image + ') no-repeat center center;background-size: cover"><span class="mino-trap"></span></a><div class="mino-content">' + labelHtml + metaHtml + '</div></div><div class="clear"></div></div>';
          }
        });
      } else {
        html += '<style>.mino-empty-panel img{max-width: 600px; width:100%}.mino-empty-panel{text-align: center;}.mino-empty-text h3{font-weight: 600;font-size:18px;line-height: 24px;margin-bottom:50px;}</style><div class="mino-empty-panel"><div class="mino-empty-thumb"><img alt="" src="https://1.bp.blogspot.com/-FCuCIgXt2v8/WdDfhsYYoZI/AAAAAAAAAhk/X-ke9mcD1KsrOnsxV2z15nup1TkXkw36wCLcBGAs/s1600/trpgrid.png"></div><div class="mino-empty-text"><h3>No posts found for label : "' + label + '". <br/> <span class="mino-small">You can disable this widget by removing all the widget content from layout tab.</span></h3></div></div>';
      }
      html += "</div>";
      content.innerHTML = html;
      content.parentElement.classList.add("minofeatured");
      content.parentElement.classList.add("pixl");
      document.querySelectorAll(".mino_featured_widget").forEach(function (section) {
        section.classList.add("mino-implied");
        section.classList.remove("mino-initiate");
      });
    });
  });
}

// ---- Sidebar feed widgets: recent comments, recent posts, posts by tag ----
var MINO_EMPTY_PANEL = '<style>.mino-empty-panel img{max-width: 600px; width:100%}.mino-empty-panel{text-align: center;}.mino-empty-text h3{font-weight: 600;font-size:18px;line-height: 24px;margin-bottom:50px;}.bgr{background: rgb(236,239,241);}.bgr{box-sizing: border-box;padding:5px 10px;}</style><div class="mino-empty-panel bgr"><div class="mino-empty-thumb"><img alt="" src="\' + MINO_NO_THUMB + \'"></div><div class="mino-empty-text"><h3>{message} <br/></h3></div></div>';

function minoRecentItemHtml(entry) {
  var url = minoEntryUrl(entry);
  var image = minoEntryImage(entry, "s400");
  return '<div class="mino-recent-item"><a aria-label="' + minoAttr(entry.title.$t) + '" class="mino-recent-thumb" href="' + url + '" style="background:url(' + image + ') no-repeat center center;background-size: cover"><span class="mino-trap"></span></a><div class="mino-recent-content"><h3 class="mino-recent-title"><a href="' + url + '">' + entry.title.$t + '</a></h3><span class="mino-author">' + entry.author[0].name.$t + '</span><span class="mino-time">' + minoFormatShortDate(entry.published.$t) + "</span></div></div>";
}

function minoRenderRecentList(span, data, emptyMessage) {
  var html = '<div class="mino-recent">';
  if (data.feed.entry) html += data.feed.entry.map(minoRecentItemHtml).join("");
  else html += MINO_EMPTY_PANEL.replace("{message}", emptyMessage);
  html += "</div>";
  span.parentElement.innerHTML = html;
}

function initSidebarFeedWidgets() {
  document.querySelectorAll(".mino-widetize .HTML .widget-content span.mino-recent").forEach(function (span) {
    minoFetchFeed("/feeds/posts/default?alt=json&max-results=" + span.getAttribute("data-no"), function (data) {
      minoRenderRecentList(span, data, "No Posts found!");
    });
  });
  document.querySelectorAll(".mino-widetize .HTML .widget-content span.mino-tagswid").forEach(function (span) {
    minoFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(span.getAttribute("data-label")) + "?alt=json&max-results=" + span.getAttribute("data-no"), function (data) {
      minoRenderRecentList(span, data, "No Posts found!");
    });
  });
  document.querySelectorAll(".mino-widetize .HTML .widget-content span.mino-cmnt").forEach(function (span) {
    minoFetchFeed("/feeds/comments/default?alt=json&max-results=" + span.getAttribute("data-no"), function (data) {
      var html = '<div class="mino-comments">';
      if (data.feed.entry) {
        data.feed.entry.forEach(function (entry) {
          var url = minoEntryUrl(entry);
          var text = (entry.content ? entry.content.$t : "").replace(/<\S[^>]*>/g, "");
          if (text.length > 70) text = text.substring(0, 50) + "...";
          var author = entry.author[0].name.$t;
          var avatar = entry.author[0].gd$image.src;
          if (avatar.indexOf("img1.blogblog.com/img/blank.gif") > -1 || avatar.indexOf("img2.blogblog.com/img/b16-rounded.gif") > -1) avatar = "https://img1.blogblog.com/img/anon36.png";
          if (avatar.indexOf("//") === 0) avatar = "https:" + avatar;
          html += '<div class="mino-comment"><div class="mino-comment-profile"><img alt="" class="mino-comment-thumb" loading="lazy" src="' + avatar + '"/></div><a href="' + url + '">' + author + '</a><span>"' + text + '"</span></div>';
        });
      } else {
        html += MINO_EMPTY_PANEL.replace("{message}", "No comments!");
      }
      html += '</div><div class="clear"></div>';
      span.parentElement.innerHTML = html;
    });
  });
}

