  document.querySelectorAll(".blsm-comment").forEach(function (trigger) {
    trigger.addEventListener("click", function () {
      var placer = document.getElementById("mino-comment-placer");
      if (placer) placer.scrollIntoView({ behavior: "smooth" });
    });
  });
}

